import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature, hasFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import type { PlanTier } from '@/lib/billing/feature-gate'

const CreateItemSchema = z.object({
  name: z.string().min(1).max(200),
  sku: z.string().max(100).optional().nullable(),
  category: z.enum(['ink', 'needle', 'supply', 'aftercare', 'equipment', 'apparel', 'other']),
  sub_category: z.string().max(100).optional().nullable(),
  brand: z.string().max(100).optional().nullable(),
  color: z.string().max(100).optional().nullable(),
  size: z.string().max(100).optional().nullable(),
  unit: z.string().min(1).max(50).default('unit'),
  current_stock: z.number().min(0).default(0),
  min_threshold: z.number().min(0).default(0),
  max_stock: z.number().min(0).optional().nullable(),
  cost_per_unit_cents: z.number().min(0).default(0),
  retail_price_cents: z.number().min(0).optional().nullable(),
  location_description: z.string().max(200).optional().nullable(),
  barcode: z.string().max(100).optional().nullable(),
  image_url: z.string().url().optional().nullable(),
  notes: z.string().max(1000).optional().nullable(),
  supplier_id: z.string().uuid().optional().nullable(),
  location_id: z.string().uuid().optional().nullable(),
})

export async function GET(request: NextRequest) {
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  const url = new URL(request.url)
  const category = url.searchParams.get('category')
  const supplier_id = url.searchParams.get('supplier_id')
  const stock_status = url.searchParams.get('stock_status')
  const location_id = url.searchParams.get('location_id')
  const is_active = url.searchParams.get('is_active') !== 'false'

  let query = supabase
    .from('inventory_items')
    .select('*, suppliers(id, name), locations(id, name)')
    .eq('studio_id', member.studio_id)
    .eq('is_active', is_active)
    .order('name')

  if (category) query = query.eq('category', category)
  if (supplier_id) query = query.eq('supplier_id', supplier_id)
  if (location_id) query = query.eq('location_id', location_id)

  const { data, error } = await query

  if (error) {
    logger.error({ err: error }, 'inventory items GET failed')
    return Response.json({ error: 'Failed to fetch items' }, { status: 500 })
  }

  let items = data ?? []

  if (stock_status === 'low') {
    items = items.filter(
      (i) => i.current_stock > 0 && i.current_stock <= i.min_threshold,
    )
  } else if (stock_status === 'out') {
    items = items.filter((i) => i.current_stock <= 0)
  }

  return Response.json({ data: items })
}

export async function POST(request: NextRequest) {
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })
  if (!['owner', 'admin'].includes(member.role)) {
    return new Response('Forbidden', { status: 403 })
  }

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  const body = CreateItemSchema.safeParse(await request.json())
