async function getContext(request: NextRequest, id: string) {
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return { error: new Response('Too many requests', { status: 429 }) }

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return { error: new Response('Unauthorized', { status: 401 }) }

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return { error: new Response('No studio membership', { status: 403 }) }

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return { error: gate }

  const { data: item } = await supabase
    .from('inventory_items')
    .select('id, studio_id')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()
  if (!item) return { error: new Response('Item not found', { status: 404 }) }

  return { supabase, user, member, item }
}

export async function GET(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const ctx = await getContext(request, id)
  if ('error' in ctx) return ctx.error

  const { data, error } = await ctx.supabase
    .from('inventory_items')
    .select('*, suppliers(id, name), locations(id, name)')
    .eq('id', id)
    .single()

  if (error || !data) return Response.json({ error: 'Item not found' }, { status: 404 })
  return Response.json({ data })
}

export async function PATCH(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const ctx = await getContext(request, id)
  if ('error' in ctx) return ctx.error

  if (!['owner', 'admin'].includes(ctx.member.role)) {
    return new Response('Forbidden', { status: 403 })
  }

  const body = UpdateItemSchema.safeParse(await request.json())
  if (!body.success) {
    return Response.json({ error: body.error.flatten() }, { status: 400 })
  }

  const { data, error } = await ctx.supabase
    .from('inventory_items')
    .update(body.data)
    .eq('id', id)
    .select()
    .single()

  if (error) {
    logger.error({ err: error }, 'inventory item update failed')
    return Response.json({ error: 'Failed to update item' }, { status: 500 })
  }

  return Response.json({ data })
}

export async function DELETE(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const ctx = await getContext(request, id)
  if ('error' in ctx) return ctx.error

  if (!['owner', 'admin'].includes(ctx.member.role)) {
    return new Response('Forbidden', { status: 403 })
  }

  // Soft-delete: set is_active = false
  const { error } = await ctx.supabase
    .from('inventory_items')
    .update({ is_active: false })
    .eq('id', id)

  if (error) {
    logger.error({ err: error }, 'inventory item soft-delete failed')
    return Response.json({ error: 'Failed to archive item' }, { status: 500 })
  }

  return new Response(null, { status: 204 })
}

import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import type { PlanTier } from '@/lib/billing/feature-gate'

const AdjustSchema = z.object({
  qty_delta: z.number().refine((n) => n !== 0, { message: 'Quantity delta cannot be zero' }),
  reason: z.enum(['adjustment', 'waste', 'return', 'stocktake', 'other']),
  notes: z.string().max(500).optional().nullable(),
})

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })
  if (!['owner', 'admin'].includes(member.role)) {
    return new Response('Forbidden', { status: 403 })
  }

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  const { data: item } = await supabase
    .from('inventory_items')
    .select('id, studio_id, current_stock')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()
  if (!item) return Response.json({ error: 'Item not found' }, { status: 404 })

  const body = AdjustSchema.safeParse(await request.json())
  if (!body.success) {
    return Response.json({ error: body.error.flatten() }, { status: 400 })
  }

  const { qty_delta, reason, notes } = body.data
  const qty_after = Number(item.current_stock) + qty_delta

  if (qty_after < 0) {
    return Response.json(
      { error: `Adjustment would result in negative stock (${qty_after})` },
      { status: 400 },
    )
  }

  // inventory_movements INSERT triggers handle_check_low_stock which updates current_stock
  const { data, error } = await supabase
    .from('inventory_movements')
    .insert({
      studio_id: member.studio_id,
      item_id: id,
      qty_delta,
      qty_after,
      reason,
      notes: notes ?? null,
      performed_by: user.id,
    })
    .select()
    .single()

  if (error) {
    logger.error({ err: error, itemId: id }, 'stock adjustment failed')
    return Response.json({ error: 'Failed to record adjustment' }, { status: 500 })
  }

  return Response.json({ data }, { status: 201 })
}

import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import type { PlanTier } from '@/lib/billing/feature-gate'

export async function GET(request: NextRequest) {
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  const url = new URL(request.url)
  const item_id = url.searchParams.get('item_id')
  const reason = url.searchParams.get('reason')
  const from = url.searchParams.get('from')
  const to = url.searchParams.get('to')
  const limit = Math.min(Number(url.searchParams.get('limit') ?? 50), 200)
  const offset = Number(url.searchParams.get('offset') ?? 0)

  let query = supabase
    .from('inventory_movements')
    .select(
      '*, inventory_items(id, name, unit), profiles(full_name)',
      { count: 'exact' },
    )
    .eq('studio_id', member.studio_id)
    .order('created_at', { ascending: false })
    .range(offset, offset + limit - 1)

  if (item_id) query = query.eq('item_id', item_id)
  if (reason) query = query.eq('reason', reason)
  if (from) query = query.gte('created_at', from)
  if (to) query = query.lte('created_at', to)

  const { data, error, count } = await query

  if (error) {
    logger.error({ err: error }, 'inventory movements GET failed')
    return Response.json({ error: 'Failed to fetch movements' }, { status: 500 })
  }

  return Response.json({ data: data ?? [], count: count ?? 0 })
}

