  end_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
  split_pct_studio: z.number().min(0).max(100).optional(),
  split_pct_artist: z.number().min(0).max(100).optional(),
  flat_fee_cents: z.number().min(0).optional().nullable(),
  studio_provides: z.array(z.string()).optional(),
  agreement_notes: z.string().max(2000).optional().nullable(),
  show_on_booking_page: z.boolean().optional(),
  calendar_color: z.string().optional().nullable(),
})

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'guest_artists')
  if (gate) return gate

  const { data, error } = await supabase.rpc('get_guest_artist_summary', {
    p_engagement_id: id,
  })

  if (error) {
    logger.error({ err: error, engagementId: id }, 'get_guest_artist_summary RPC failed')
    return Response.json({ error: 'Failed to fetch engagement' }, { status: 500 })
  }

  if (!data) return Response.json({ error: 'Engagement not found' }, { status: 404 })

  return Response.json({ data })
}

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })
  if (!['owner', 'admin'].includes(member.role)) return new Response('Forbidden', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'guest_artists')
  if (gate) return gate

  const { data: engagement } = await supabase
    .from('guest_artist_engagements')
    .select('id, status')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()
  if (!engagement) return Response.json({ error: 'Engagement not found' }, { status: 404 })
  if (engagement.status === 'completed' || engagement.status === 'cancelled') {
    return Response.json({ error: 'Cannot edit a completed or cancelled engagement' }, { status: 400 })
  }

  const body = UpdateEngagementSchema.safeParse(await request.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { data, error } = await supabase
    .from('guest_artist_engagements')
    .update(body.data)
    .eq('id', id)
    .select()
    .single()

  if (error) {
    logger.error({ err: error, engagementId: id }, 'engagement update failed')
    return Response.json({ error: 'Failed to update engagement' }, { status: 500 })
  }

  return Response.json({ data })
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })
  if (member.role !== 'owner') return new Response('Forbidden', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'guest_artists')
  if (gate) return gate

  const { error } = await supabase
    .from('guest_artist_engagements')
    .update({ status: 'cancelled' })
    .eq('id', id)
    .eq('studio_id', member.studio_id)

  if (error) {
    logger.error({ err: error, engagementId: id }, 'engagement cancel failed')
    return Response.json({ error: 'Failed to cancel engagement' }, { status: 500 })
  }

  return new Response(null, { status: 204 })
}

import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import type { PlanTier } from '@/lib/billing/feature-gate'

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })
  if (!['owner', 'admin'].includes(member.role)) return new Response('Forbidden', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'guest_artists')
  if (gate) return gate

  const { data: engagement } = await supabase
    .from('guest_artist_engagements')
    .select('id, status')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()
  if (!engagement) return Response.json({ error: 'Engagement not found' }, { status: 404 })
  if (engagement.status === 'completed' || engagement.status === 'cancelled') {
    return Response.json({ error: 'Engagement is already ended' }, { status: 400 })
  }

  const { data, error } = await supabase.rpc('end_guest_engagement', {
    p_engagement_id: id,
  })

  if (error) {
    logger.error({ err: error, engagementId: id }, 'end_guest_engagement RPC failed')
    return Response.json({ error: 'Failed to end engagement' }, { status: 500 })
  }

  return Response.json({ data })
}

