export function StockLevelBadge({ current, min, className }: StockLevelBadgeProps) {
  const isOut = current <= 0
  const isLow = !isOut && current <= min

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium tabular-nums',
        isOut && 'bg-[oklch(59%_0.22_27/0.15)] text-[oklch(59%_0.22_27)]',
        isLow && !isOut && 'bg-[oklch(70%_0.16_72/0.15)] text-[oklch(60%_0.16_72)]',
        !isLow && !isOut && 'bg-[oklch(58%_0.18_145/0.15)] text-[oklch(50%_0.18_145)]',
        className,
      )}
    >
      {current}
    </span>
  )
}

