type ItemWithRelations = InventoryItem & {
  suppliers: { id: string; name: string } | null
  locations: { id: string; name: string } | null
}

export function ItemsTable() {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [categoryFilter, setCategoryFilter] = useState('all')
  const [stockFilter, setStockFilter] = useState('all')
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editItem, setEditItem] = useState<ItemWithRelations | null>(null)
  const [adjustItem, setAdjustItem] = useState<ItemWithRelations | null>(null)

  const params = new URLSearchParams()
  if (categoryFilter !== 'all') params.set('category', categoryFilter)
  if (stockFilter !== 'all') params.set('stock_status', stockFilter)

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.items({ category: categoryFilter, stock_status: stockFilter }),
    queryFn: async () => {
      const res = await fetch(`/api/inventory/items?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch items')
      const json = await res.json() as { data: ItemWithRelations[] }
      return json.data
    },
  })

  const archiveMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/inventory/items/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to archive item')
    },
    onSuccess: () => {
      toast.success('Item archived')
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
    },
    onError: () => toast.error('Failed to archive item'),
  })

  const filtered = (data ?? []).filter((item) => {
    if (!search) return true
    const q = search.toLowerCase()
    return (
      item.name.toLowerCase().includes(q) ||
      item.sku?.toLowerCase().includes(q) ||
      item.brand?.toLowerCase().includes(q)
    )
  })

  if (isLoading) {
    return (
      <div className="space-y-2 p-1">
        {Array.from({ length: 6 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full" />
        ))}
      </div>
    )
  }

  return (
    <>
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-1 items-center gap-2">
          <div className="relative flex-1 max-w-xs">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search items..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8 h-8"
            />
          </div>
          <Select value={categoryFilter} onValueChange={setCategoryFilter}>
            <SelectTrigger className="h-8 w-32">
              <SlidersHorizontal className="mr-1.5 h-3.5 w-3.5 text-muted-foreground" />
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              <SelectItem value="ink">Ink</SelectItem>
              <SelectItem value="needle">Needle</SelectItem>
              <SelectItem value="supply">Supply</SelectItem>
              <SelectItem value="aftercare">Aftercare</SelectItem>
              <SelectItem value="equipment">Equipment</SelectItem>
              <SelectItem value="apparel">Apparel</SelectItem>
              <SelectItem value="other">Other</SelectItem>
            </SelectContent>
          </Select>
          <Select value={stockFilter} onValueChange={setStockFilter}>
            <SelectTrigger className="h-8 w-32">
              <SelectValue placeholder="Stock" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Stock</SelectItem>
              <SelectItem value="low">Low Stock</SelectItem>
              <SelectItem value="out">Out of Stock</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <Button
          size="sm"
          onClick={() => { setEditItem(null); setDrawerOpen(true) }}
          className="shrink-0"
        >
          <Plus className="mr-1.5 h-4 w-4" />
          Add Item
        </Button>
      </div>

      {filtered.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-3">
          <div className="rounded-xl bg-muted/50 p-4">
            <Archive className="h-8 w-8 text-muted-foreground/50" />
          </div>
          <div className="text-center space-y-1">
            <p className="text-sm font-medium">No items found</p>
            <p className="text-xs text-muted-foreground">
              {search || categoryFilter !== 'all' || stockFilter !== 'all'
                ? 'Try adjusting your filters'
                : 'Add your first inventory item to get started'}
            </p>
          </div>
          {!search && categoryFilter === 'all' && stockFilter === 'all' && (
            <Button
              size="sm"
              variant="outline"
              onClick={() => { setEditItem(null); setDrawerOpen(true) }}
            >
              <Plus className="mr-1.5 h-4 w-4" />
              Add Item
            </Button>
          )}
        </div>
      ) : (
        <div className="rounded-lg border border-border overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/30 hover:bg-muted/30">
                <TableHead className="text-xs">Name</TableHead>
                <TableHead className="text-xs">Category</TableHead>
                <TableHead className="text-xs">Brand</TableHead>
                <TableHead className="text-xs text-right">Stock</TableHead>
                <TableHead className="text-xs text-right">Cost/Unit</TableHead>
                <TableHead className="text-xs">Supplier</TableHead>
                <TableHead className="w-10" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {filtered.map((item) => (
                <TableRow key={item.id} className="group">
                  <TableCell>
                    <div className="flex flex-col gap-0.5">
                      <span className="text-sm font-medium">{item.name}</span>
                      {item.sku && (
