const PAGE_SIZE = 25

export function MovementsLog() {
  const [reason, setReason] = useState('all')
  const [from, setFrom] = useState('')
  const [to, setTo] = useState('')
  const [page, setPage] = useState(0)

  const params = new URLSearchParams()
  if (reason !== 'all') params.set('reason', reason)
  if (from) params.set('from', from)
  if (to) params.set('to', to)
  params.set('limit', String(PAGE_SIZE))
  params.set('offset', String(page * PAGE_SIZE))

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.movements({ reason, from, to, page }),
    queryFn: async () => {
      const res = await fetch(`/api/inventory/movements?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch movements')
      const json = await res.json() as { data: MovementWithRelations[]; count: number }
      return json
    },
  })

  const movements = data?.data ?? []
  const total = data?.count ?? 0
  const hasNext = (page + 1) * PAGE_SIZE < total
  const hasPrev = page > 0

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 8 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full" />
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2">
        <Select value={reason} onValueChange={(v) => { setReason(v); setPage(0) }}>
          <SelectTrigger className="h-8 w-36">
            <SelectValue placeholder="Reason" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Reasons</SelectItem>
            <SelectItem value="purchase">Purchase</SelectItem>
            <SelectItem value="session_use">Session Use</SelectItem>
            <SelectItem value="adjustment">Adjustment</SelectItem>
            <SelectItem value="waste">Waste</SelectItem>
            <SelectItem value="return">Return</SelectItem>
            <SelectItem value="stocktake">Stocktake</SelectItem>
            <SelectItem value="other">Other</SelectItem>
          </SelectContent>
        </Select>
        <div className="flex items-center gap-1.5">
          <span className="text-xs text-muted-foreground">From</span>
          <Input
            type="date"
            value={from}
            onChange={(e) => { setFrom(e.target.value); setPage(0) }}
            className="h-8 w-36"
          />
        </div>
        <div className="flex items-center gap-1.5">
          <span className="text-xs text-muted-foreground">To</span>
          <Input
            type="date"
            value={to}
            onChange={(e) => { setTo(e.target.value); setPage(0) }}
            className="h-8 w-36"
          />
        </div>
        {(reason !== 'all' || from || to) && (
          <Button
            variant="ghost"
            size="sm"
            className="h-8 text-xs"
            onClick={() => { setReason('all'); setFrom(''); setTo(''); setPage(0) }}
          >
            Clear filters
          </Button>
        )}
        <span className="ml-auto text-xs text-muted-foreground">
          {total} movement{total !== 1 ? 's' : ''}
        </span>
      </div>

      {movements.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-3">
          <div className="rounded-xl bg-muted/50 p-4">
            <PackageOpen className="h-8 w-8 text-muted-foreground/50" />
          </div>
          <div className="text-center space-y-1">
            <p className="text-sm font-medium">No movements recorded</p>
            <p className="text-xs text-muted-foreground">
              Stock changes will appear here as a read-only audit log
            </p>
          </div>
        </div>
      ) : (
        <>
          <div className="rounded-lg border border-border overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow className="bg-muted/30 hover:bg-muted/30">
                  <TableHead className="text-xs">Date</TableHead>
                  <TableHead className="text-xs">Item</TableHead>
                  <TableHead className="text-xs text-right">Delta</TableHead>
                  <TableHead className="text-xs text-right">After</TableHead>
                  <TableHead className="text-xs">Reason</TableHead>
                  <TableHead className="text-xs">By</TableHead>
                  <TableHead className="text-xs">Notes</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {movements.map((m) => {
                  const isPositive = m.qty_delta > 0
                  return (
                    <TableRow key={m.id}>
                      <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                        {formatDate(m.created_at, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                      </TableCell>
                      <TableCell>
                        <span className="text-sm font-medium">
                          {m.inventory_items?.name ?? '—'}
                        </span>
                      </TableCell>
                      <TableCell className="text-right">
                        <span
                          className={`inline-flex items-center gap-0.5 text-sm font-semibold tabular-nums ${
                            isPositive
                              ? 'text-[oklch(50%_0.18_145)]'
                              : 'text-[oklch(59%_0.22_27)]'
                          }`}
                        >
                          {isPositive ? (
                            <ArrowUp className="h-3 w-3" />
                          ) : (
                            <ArrowDown className="h-3 w-3" />
                          )}
                          {isPositive ? '+' : ''}
                          {m.qty_delta} {m.inventory_items?.unit ?? ''}
                        </span>
                      </TableCell>
                      <TableCell className="text-right text-sm tabular-nums text-muted-foreground">
                        {m.qty_after} {m.inventory_items?.unit ?? ''}
                      </TableCell>
                      <TableCell>
                        <span
                          className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium ${REASON_COLORS[m.reason]}`}
                        >
                          {REASON_LABELS[m.reason]}
                        </span>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground">
                        {m.profiles?.full_name ?? '—'}
                      </TableCell>
                      <TableCell className="max-w-[180px]">
                        {m.notes ? (
                          <span className="text-xs text-muted-foreground truncate block">
                            {m.notes}
                          </span>
                        ) : (
                          <span className="text-xs text-muted-foreground/40">—</span>
                        )}
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </div>

          {/* Pagination */}
          {total > PAGE_SIZE && (
            <div className="flex items-center justify-between">
              <p className="text-xs text-muted-foreground">
                Showing {page * PAGE_SIZE + 1}–{Math.min((page + 1) * PAGE_SIZE, total)} of {total}
              </p>
              <div className="flex gap-1">
                <Button
                  variant="outline"
                  size="icon"
                  className="h-7 w-7"
                  disabled={!hasPrev}
                  onClick={() => setPage((p) => p - 1)}
                >
                  <ChevronLeft className="h-3.5 w-3.5" />
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  className="h-7 w-7"
                  disabled={!hasNext}
                  onClick={() => setPage((p) => p + 1)}
                >
                  <ChevronRight className="h-3.5 w-3.5" />
                </Button>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Skeleton } from '@/components/ui/skeleton'
import { SupplierForm } from '@/components/inventory/SupplierForm'
import { queryKeys } from '@/lib/query-keys'
import { toast } from 'sonner'
import { Plus, Search, MoreHorizontal, Edit, Archive, Truck } from 'lucide-react'
import type { Supplier } from '@/lib/supabase/types'

type SupplierWithCount = Supplier & { inventory_items: { id: string }[] }

export function SuppliersTable() {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editSupplier, setEditSupplier] = useState<Supplier | null>(null)

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.suppliers(),
    queryFn: async () => {
      const res = await fetch('/api/inventory/suppliers')
      if (!res.ok) throw new Error('Failed to fetch suppliers')
      const json = await res.json() as { data: SupplierWithCount[] }
      return json.data
    },
  })

  const archiveMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/inventory/suppliers/${id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to archive supplier')
    },
    onSuccess: () => {
      toast.success('Supplier archived')
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.suppliers() })
    },
    onError: () => toast.error('Failed to archive supplier'),
  })

  const filtered = (data ?? []).filter((s) => {
    if (!search) return true
    const q = search.toLowerCase()
    return s.name.toLowerCase().includes(q) || s.email?.toLowerCase().includes(q)
  })

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full" />
        ))}
      </div>
    )
  }

  return (
    <>
      <div className="flex items-center gap-2 justify-between">
        <div className="relative max-w-xs flex-1">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search suppliers..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-8 h-8"
          />
        </div>
        <Button
          size="sm"
          onClick={() => { setEditSupplier(null); setDrawerOpen(true) }}
          className="shrink-0"
        >
          <Plus className="mr-1.5 h-4 w-4" />
          Add Supplier
        </Button>
      </div>

      {filtered.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-3">
          <div className="rounded-xl bg-muted/50 p-4">
            <Truck className="h-8 w-8 text-muted-foreground/50" />
          </div>
          <div className="text-center space-y-1">
            <p className="text-sm font-medium">No suppliers found</p>
            <p className="text-xs text-muted-foreground">
              {search ? 'Try adjusting your search' : 'Add your first supplier to track orders'}
            </p>
          </div>
          {!search && (
            <Button
              size="sm"
              variant="outline"
              onClick={() => { setEditSupplier(null); setDrawerOpen(true) }}
            >
              <Plus className="mr-1.5 h-4 w-4" />
              Add Supplier
            </Button>
          )}
        </div>
      ) : (
        <div className="rounded-lg border border-border overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/30 hover:bg-muted/30">
                <TableHead className="text-xs">Name</TableHead>
                <TableHead className="text-xs">Contact</TableHead>
                <TableHead className="text-xs">Email</TableHead>
                <TableHead className="text-xs">Phone</TableHead>
                <TableHead className="text-xs text-right">Items</TableHead>
                <TableHead className="w-10" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {filtered.map((supplier) => (
                <TableRow key={supplier.id} className="group">
                  <TableCell>
                    <span className="text-sm font-medium">{supplier.name}</span>
                  </TableCell>
                  <TableCell>
                    <span className="text-sm text-muted-foreground">
                      {supplier.contact_name ?? '—'}
                    </span>
                  </TableCell>
                  <TableCell>
                    {supplier.email ? (
                      <a
                        href={`mailto:${supplier.email}`}
                        className="text-sm text-primary hover:underline"
                      >
                        {supplier.email}
                      </a>
                    ) : (
                      <span className="text-sm text-muted-foreground">—</span>
                    )}
                  </TableCell>
                  <TableCell>
                    <span className="text-sm text-muted-foreground">
                      {supplier.phone ?? '—'}
                    </span>
                  </TableCell>
                  <TableCell className="text-right">
                    <span className="text-sm tabular-nums">
                      {supplier.inventory_items?.length ?? 0}
                    </span>
                  </TableCell>
                  <TableCell>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 opacity-0 group-hover:opacity-100"
                        >
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem
                          onClick={() => { setEditSupplier(supplier); setDrawerOpen(true) }}
                        >
                          <Edit className="mr-2 h-4 w-4" />
                          Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          className="text-destructive focus:text-destructive"
                          onClick={() => archiveMutation.mutate(supplier.id)}
                        >
                          <Archive className="mr-2 h-4 w-4" />
                          Archive
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}

      <SupplierForm
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        supplier={editSupplier}
        onSuccess={() => {
          void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.suppliers() })
        }}
      />
    </>
  )
}

'use client'

import { useEffect } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useMutation } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { toast } from 'sonner'
import type { Supplier } from '@/lib/supabase/types'

const schema = z.object({
  name: z.string().min(1, 'Name is required').max(200),
  contact_name: z.string().max(200).optional().nullable(),
  email: z.string().email('Invalid email').max(200).optional().nullable().or(z.literal('')),
  phone: z.string().max(50).optional().nullable(),
  website: z.string().url('Invalid URL').max(500).optional().nullable().or(z.literal('')),
  notes: z.string().max(1000).optional().nullable(),
})

type FormValues = z.infer<typeof schema>

interface SupplierFormProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  supplier?: Supplier | null
  onSuccess?: () => void
}

export function SupplierForm({ open, onOpenChange, supplier, onSuccess }: SupplierFormProps) {
  const isEdit = Boolean(supplier)

  const form = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: { name: '', contact_name: null, email: null, phone: null, website: null, notes: null },
  })

  useEffect(() => {
    if (!open) return
    if (supplier) {
      form.reset({
        name: supplier.name,
        contact_name: supplier.contact_name,
        email: supplier.email,
        phone: supplier.phone,
        website: supplier.website,
        notes: supplier.notes,
      })
    } else {
      form.reset({ name: '', contact_name: null, email: null, phone: null, website: null, notes: null })
    }
  }, [open, supplier, form])

  const mutation = useMutation({
    mutationFn: async (values: FormValues) => {
      const cleaned = {
        ...values,
        email: values.email === '' ? null : values.email,
        website: values.website === '' ? null : values.website,
      }
      const url = isEdit ? `/api/inventory/suppliers/${supplier!.id}` : '/api/inventory/suppliers'
      const method = isEdit ? 'PATCH' : 'POST'
      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(cleaned),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to save supplier')
      }
      return res.json()
    },
    onSuccess: () => {
      toast.success(isEdit ? 'Supplier updated' : 'Supplier created')
      onOpenChange(false)
      onSuccess?.()
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to save supplier')
    },
  })

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-md overflow-y-auto">
        <SheetHeader>
          <SheetTitle>{isEdit ? 'Edit Supplier' : 'Add Supplier'}</SheetTitle>
          <SheetDescription>
            {isEdit ? 'Update supplier details' : 'Add a supplier to link to inventory items and purchase orders'}
          </SheetDescription>
        </SheetHeader>

        <Form {...form}>
          <form
            onSubmit={form.handleSubmit((v) => mutation.mutate(v))}
            className="mt-6 space-y-4"
          >
            <FormField
              control={form.control}
              name="name"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Company Name</FormLabel>
                  <FormControl>
                    <Input placeholder="Intenze Products Inc." {...field} value={field.value ?? ''} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="contact_name"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Contact Name</FormLabel>
                  <FormControl>
                    <Input placeholder="Sales rep name" {...field} value={field.value ?? ''} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="grid grid-cols-2 gap-3">
              <FormField
                control={form.control}
                name="email"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Email</FormLabel>
                    <FormControl>
                      <Input
                        type="email"
                        placeholder="orders@supplier.com"
                        {...field}
                        value={field.value ?? ''}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="phone"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Phone</FormLabel>
                    <FormControl>
                      <Input placeholder="+1 555-555-5555" {...field} value={field.value ?? ''} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="website"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Website</FormLabel>
                  <FormControl>
                    <Input
                      type="url"
                      placeholder="https://supplier.com"
                      {...field}
                      value={field.value ?? ''}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="notes"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Notes</FormLabel>
                  <FormControl>
                    <Textarea
                      rows={3}
                      placeholder="Payment terms, lead times, special instructions..."
                      {...field}
                      value={field.value ?? ''}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="flex gap-2 pt-2">
              <Button
                type="button"
                variant="outline"
                className="flex-1"
                onClick={() => onOpenChange(false)}
              >
                Cancel
              </Button>
              <Button type="submit" className="flex-1" disabled={mutation.isPending}>
                {mutation.isPending ? 'Saving...' : isEdit ? 'Update Supplier' : 'Add Supplier'}
              </Button>
            </div>
          </form>
        </Form>
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { queryKeys } from '@/lib/query-keys'
import { formatDate, formatRelativeTime } from '@/lib/utils'
import { toast } from 'sonner'
import { AlertTriangle, PackageX, TrendingUp, CheckCircle2, Bell } from 'lucide-react'
import type { StockAlert } from '@/lib/supabase/types'

type AlertWithItem = StockAlert & {
  inventory_items: { id: string; name: string; unit: string; current_stock: number; min_threshold: number } | null
}

const ALERT_CONFIG = {
  low_stock: {
    icon: AlertTriangle,
    label: 'Low Stock',
    color: 'text-[oklch(60%_0.16_72)]',
    bg: 'bg-[oklch(70%_0.16_72/0.1)]',
    border: 'border-[oklch(70%_0.16_72/0.3)]',
  },
  out_of_stock: {
    icon: PackageX,
    label: 'Out of Stock',
    color: 'text-[oklch(59%_0.22_27)]',
    bg: 'bg-[oklch(59%_0.22_27/0.1)]',
    border: 'border-[oklch(59%_0.22_27/0.3)]',
  },
  overstock: {
    icon: TrendingUp,
    label: 'Overstock',
    color: 'text-[oklch(60%_0.2_200)]',
    bg: 'bg-[oklch(60%_0.2_200/0.1)]',
    border: 'border-[oklch(60%_0.2_200/0.3)]',
  },
} as const

export function StockAlertsPanel() {
  const queryClient = useQueryClient()

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.stockAlerts(),
    queryFn: async () => {
      const res = await fetch('/api/inventory/stock-alerts')
      if (!res.ok) throw new Error('Failed to fetch stock alerts')
      const json = await res.json() as { data: AlertWithItem[] }
      return json.data
    },
  })

  const acknowledgeMutation = useMutation({
    mutationFn: async ({ id, notes }: { id: string; notes?: string }) => {
      const res = await fetch('/api/inventory/stock-alerts', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, notes }),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to acknowledge alert')
      }
      return res.json()
    },
    onSuccess: () => {
      toast.success('Alert acknowledged')
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.stockAlerts() })
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.dashboard() })
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to acknowledge alert')
    },
  })

  const acknowledgeAll = () => {
    const alerts = data ?? []
    if (alerts.length === 0) return
    alerts.forEach((a) => {
      acknowledgeMutation.mutate({ id: a.id })
    })
  }

  if (isLoading) {
    return (
      <div className="space-y-3">
        {Array.from({ length: 4 }).map((_, i) => (
          <Skeleton key={i} className="h-16 w-full" />
        ))}
      </div>
    )
  }

  const alerts = data ?? []

  if (alerts.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-3">
        <div className="rounded-xl bg-muted/50 p-4">
          <CheckCircle2 className="h-8 w-8 text-[oklch(50%_0.18_145)]" />
        </div>
        <div className="text-center space-y-1">
          <p className="text-sm font-medium">All clear</p>
          <p className="text-xs text-muted-foreground">
            No open stock alerts. Your inventory is within normal levels.
          </p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Bell className="h-4 w-4 text-muted-foreground" />
          <span className="text-sm font-medium">{alerts.length} open alert{alerts.length !== 1 ? 's' : ''}</span>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={acknowledgeAll}
          disabled={acknowledgeMutation.isPending}
        >
          Acknowledge All
        </Button>
      </div>

      <div className="space-y-2">
        {alerts.map((alert) => {
          const config = ALERT_CONFIG[alert.alert_type]
          const Icon = config.icon
          const item = alert.inventory_items

          return (
            <div
              key={alert.id}
              className={`flex items-start gap-3 rounded-lg border p-3 ${config.bg} ${config.border}`}
            >
              <div className={`mt-0.5 shrink-0 ${config.color}`}>
                <Icon className="h-4 w-4" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <p className="text-sm font-medium">
                      {item?.name ?? 'Unknown item'}
                    </p>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      <span className={`font-medium ${config.color}`}>{config.label}</span>
                      {item && (
                        <>
                          {' · '}Current: {Number(item.current_stock)} {item.unit}
                          {alert.alert_type !== 'overstock' && (
                            <> · Min: {Number(item.min_threshold)} {item.unit}</>
                          )}
                        </>
                      )}
                      {' · '}
                      {formatRelativeTime(alert.created_at)}
                    </p>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-7 text-xs shrink-0"
                    disabled={acknowledgeMutation.isPending}
                    onClick={() => acknowledgeMutation.mutate({ id: alert.id })}
                  >
                    Acknowledge
                  </Button>
                </div>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { CategoryBadge } from '@/components/inventory/CategoryBadge'
import { queryKeys } from '@/lib/query-keys'
import { toast } from 'sonner'
import { Search, ClipboardList, CheckCircle2 } from 'lucide-react'
import type { InventoryItem } from '@/lib/supabase/types'

type CountedItem = { item_id: string; actual_qty: number }

export function StocktakeForm() {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [categoryFilter, setCategoryFilter] = useState('all')
  const [counts, setCounts] = useState<Record<string, string>>({})
  const [submitted, setSubmitted] = useState(false)

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.items({ is_active: true }),
    queryFn: async () => {
      const res = await fetch('/api/inventory/items')
      if (!res.ok) throw new Error('Failed to fetch items')
      const json = await res.json() as { data: InventoryItem[] }
      return json.data
    },
  })

  const filtered = useMemo(() => {
    return (data ?? []).filter((item) => {
      const matchesCategory = categoryFilter === 'all' || item.category === categoryFilter
      const matchesSearch = !search || item.name.toLowerCase().includes(search.toLowerCase())
      return matchesCategory && matchesSearch
    })
  }, [data, categoryFilter, search])

  const countedCount = Object.values(counts).filter((v) => v !== '').length

  const mutation = useMutation({
    mutationFn: async () => {
      const items: CountedItem[] = Object.entries(counts)
        .filter(([, v]) => v !== '')
        .map(([item_id, v]) => ({ item_id, actual_qty: parseFloat(v) }))

      if (items.length === 0) throw new Error('Count at least one item')

      const res = await fetch('/api/inventory/stocktake', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items }),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Stocktake failed')
      }
      return res.json()
    },
    onSuccess: () => {
      toast.success(`Stocktake complete — ${countedCount} item${countedCount !== 1 ? 's' : ''} updated`)
      setCounts({})
      setSubmitted(true)
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.movements() })
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.stockAlerts() })
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Stocktake failed')
    },
  })

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 8 }).map((_, i) => (
          <Skeleton key={i} className="h-12 w-full" />
        ))}
      </div>
    )
  }

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <div className="rounded-xl bg-[oklch(58%_0.18_145/0.15)] p-4">
          <CheckCircle2 className="h-8 w-8 text-[oklch(48%_0.18_145)]" />
        </div>
        <div className="text-center space-y-1">
          <p className="text-sm font-medium">Stocktake submitted</p>
          <p className="text-xs text-muted-foreground">Stock levels have been updated</p>
        </div>
        <Button variant="outline" size="sm" onClick={() => setSubmitted(false)}>
          Start new stocktake
        </Button>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-2 justify-between">
        <div className="flex items-center gap-2">
          <div className="relative max-w-xs">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search items..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-8 h-8 w-56"
            />
          </div>
          <Select value={categoryFilter} onValueChange={setCategoryFilter}>
            <SelectTrigger className="h-8 w-32">
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              <SelectItem value="ink">Ink</SelectItem>
              <SelectItem value="needle">Needle</SelectItem>
              <SelectItem value="supply">Supply</SelectItem>
              <SelectItem value="aftercare">Aftercare</SelectItem>
              <SelectItem value="equipment">Equipment</SelectItem>
              <SelectItem value="apparel">Apparel</SelectItem>
              <SelectItem value="other">Other</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="flex items-center gap-2">
          {countedCount > 0 && (
            <span className="text-xs text-muted-foreground">
              {countedCount} item{countedCount !== 1 ? 's' : ''} counted
            </span>
          )}
          <Button
            size="sm"
            disabled={countedCount === 0 || mutation.isPending}
            onClick={() => mutation.mutate()}
          >
            <ClipboardList className="mr-1.5 h-4 w-4" />
            {mutation.isPending ? 'Submitting...' : 'Submit Stocktake'}
          </Button>
        </div>
      </div>

      {/* Item count grid */}
      <div className="rounded-lg border border-border divide-y divide-border">
        {filtered.length === 0 ? (
          <div className="py-12 text-center text-sm text-muted-foreground">No items found</div>
        ) : (
          filtered.map((item) => (
            <div key={item.id} className="flex items-center gap-3 px-4 py-2.5">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium truncate">{item.name}</span>
                  <CategoryBadge category={item.category} />
                </div>
                <p className="text-xs text-muted-foreground mt-0.5">
                  System: {Number(item.current_stock)} {item.unit}
                  {item.brand && ` · ${item.brand}`}
                </p>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <span className="text-xs text-muted-foreground w-8 text-right">Actual</span>
                <Input
                  type="number"
                  step="0.5"
                  min="0"
                  placeholder={String(Number(item.current_stock))}
                  value={counts[item.id] ?? ''}
                  onChange={(e) => setCounts((prev) => ({ ...prev, [item.id]: e.target.value }))}
                  className={`h-8 w-24 text-right ${
                    counts[item.id] !== undefined && counts[item.id] !== ''
                      ? 'border-primary ring-1 ring-primary/20'
                      : ''
                  }`}
                />
                <span className="text-xs text-muted-foreground w-8">{item.unit}</span>
              </div>
            </div>
          ))
        )}
      </div>

      {countedCount > 0 && (
        <div className="flex justify-end">
          <Button
            disabled={mutation.isPending}
            onClick={() => mutation.mutate()}
          >
            <ClipboardList className="mr-1.5 h-4 w-4" />
            {mutation.isPending ? 'Submitting...' : `Submit ${countedCount} Count${countedCount !== 1 ? 's' : ''}`}
          </Button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Skeleton } from '@/components/ui/skeleton'
import { CategoryBadge } from '@/components/inventory/CategoryBadge'
import { queryKeys } from '@/lib/query-keys'
import { toast } from 'sonner'
import { PackageMinus } from 'lucide-react'
import type { InventoryItem } from '@/lib/supabase/types'

interface UsageLine {
  item_id: string
  qty_used: number
}

interface SessionUsageModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  bookingId: string
  bookingLabel?: string
  onSuccess?: () => void
}

export function SessionUsageModal({
  open,
  onOpenChange,
  bookingId,
  bookingLabel,
  onSuccess,
}: SessionUsageModalProps) {
  const queryClient = useQueryClient()
  const [quantities, setQuantities] = useState<Record<string, string>>({})

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.items({ is_active: true }),
    queryFn: async () => {
      const res = await fetch('/api/inventory/items')
      if (!res.ok) throw new Error('Failed to fetch items')
      const json = await res.json() as { data: InventoryItem[] }
      return json.data
    },
    enabled: open,
  })

  const items = (data ?? []).filter((i) =>
    ['ink', 'needle', 'supply', 'aftercare'].includes(i.category)
  )

  const usageLines: UsageLine[] = Object.entries(quantities)
    .filter(([, v]) => v !== '' && parseFloat(v) > 0)
    .map(([item_id, v]) => ({ item_id, qty_used: parseFloat(v) }))

  const mutation = useMutation({
    mutationFn: async () => {
      if (usageLines.length === 0) throw new Error('Record at least one item used')

      const res = await fetch('/api/inventory/session-usage', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ booking_id: bookingId, items: usageLines }),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to record usage')
      }
      return res.json()
    },
    onSuccess: () => {
      toast.success('Session usage recorded')
      onOpenChange(false)
      setQuantities({})
      onSuccess?.()
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.movements() })
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to record usage')
    },
  })

  const handleClose = () => {
    onOpenChange(false)
    setQuantities({})
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-lg max-h-[80vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <PackageMinus className="h-4 w-4" />
            Record Session Usage
          </DialogTitle>
          <DialogDescription>
            {bookingLabel
              ? `Enter quantities used for: ${bookingLabel}`
              : 'Enter quantities used during this session'}
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto -mx-6 px-6">
          {isLoading ? (
            <div className="space-y-2 py-2">
              {Array.from({ length: 6 }).map((_, i) => (
                <Skeleton key={i} className="h-12 w-full" />
              ))}
            </div>
          ) : items.length === 0 ? (
            <div className="py-8 text-center text-sm text-muted-foreground">
              No consumable items in inventory
            </div>
          ) : (
            <div className="divide-y divide-border py-2">
              {items.map((item) => (
                <div key={item.id} className="flex items-center gap-3 py-2.5">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-medium truncate">{item.name}</span>
                      <CategoryBadge category={item.category} />
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Stock: {Number(item.current_stock)} {item.unit}
                    </p>
                  </div>
                  <div className="flex items-center gap-1.5 shrink-0">
                    <Input
                      type="number"
                      step="0.5"
                      min="0"
                      placeholder="0"
                      value={quantities[item.id] ?? ''}
                      onChange={(e) =>
                        setQuantities((prev) => ({ ...prev, [item.id]: e.target.value }))
                      }
                      className="h-8 w-20 text-right"
                    />
                    <span className="text-xs text-muted-foreground w-8">{item.unit}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <DialogFooter className="pt-4 border-t border-border">
          <Button variant="outline" onClick={handleClose}>
            Cancel
          </Button>
          <Button
            onClick={() => mutation.mutate()}
            disabled={usageLines.length === 0 || mutation.isPending}
          >
            {mutation.isPending
              ? 'Recording...'
              : `Record ${usageLines.length > 0 ? `${usageLines.length} item${usageLines.length !== 1 ? 's' : ''}` : 'Usage'}`}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useForm, useFieldArray } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useQuery, useMutation } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { toast } from 'sonner'
import { queryKeys } from '@/lib/query-keys'
import { formatCurrency } from '@/lib/utils'
import { Plus, Trash2 } from 'lucide-react'
import type { Supplier, InventoryItem } from '@/lib/supabase/types'

const lineSchema = z.object({
  item_id: z.string().uuid('Select an item'),
  qty_ordered: z.coerce.number().min(1, 'Minimum 1'),
  unit_cost_cents: z.coerce.number().min(0),
  notes: z.string().max(500).optional().nullable(),
})

const schema = z.object({
  supplier_id: z.string().uuid().optional().nullable(),
  order_number: z.string().min(1, 'Order number required').max(100),
  notes: z.string().max(1000).optional().nullable(),
  ordered_at: z.string().optional().nullable(),
  expected_delivery_at: z.string().optional().nullable(),
  lines: z.array(lineSchema).min(1, 'Add at least one item'),
})

type FormValues = z.infer<typeof schema>

interface PurchaseOrderFormProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSuccess?: () => void
}

export function PurchaseOrderForm({ open, onOpenChange, onSuccess }: PurchaseOrderFormProps) {
  const form = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      supplier_id: null,
      order_number: `PO-${Date.now().toString(36).toUpperCase()}`,
      notes: null,
      ordered_at: null,
      expected_delivery_at: null,
      lines: [{ item_id: '', qty_ordered: 1, unit_cost_cents: 0, notes: null }],
    },
  })

  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: 'lines',
  })

  const { data: suppliersData } = useQuery({
    queryKey: queryKeys.inventory.suppliers(),
    queryFn: async () => {
      const res = await fetch('/api/inventory/suppliers')
      if (!res.ok) throw new Error('Failed to fetch suppliers')
      const json = await res.json() as { data: Supplier[] }
      return json.data
    },
    enabled: open,
  })

  const { data: itemsData } = useQuery({
    queryKey: queryKeys.inventory.items(),
    queryFn: async () => {
      const res = await fetch('/api/inventory/items')
      if (!res.ok) throw new Error('Failed to fetch items')
      const json = await res.json() as { data: InventoryItem[] }
      return json.data
    },
    enabled: open,
  })

  useEffect(() => {
    if (!open) return
    form.reset({
      supplier_id: null,
      order_number: `PO-${Date.now().toString(36).toUpperCase()}`,
      notes: null,
      ordered_at: null,
      expected_delivery_at: null,
      lines: [{ item_id: '', qty_ordered: 1, unit_cost_cents: 0, notes: null }],
    })
  }, [open, form])

  const mutation = useMutation({
    mutationFn: async (values: FormValues) => {
      const res = await fetch('/api/inventory/purchase-orders', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(values),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to create order')
      }
      return res.json()
    },
    onSuccess: () => {
      toast.success('Purchase order created')
      onOpenChange(false)
      onSuccess?.()
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to create order')
    },
  })

  const lines = form.watch('lines')
  const orderTotal = lines.reduce((sum, l) => {
    const qty = Number(l.qty_ordered) || 0
    const cost = Number(l.unit_cost_cents) || 0
    return sum + qty * cost
  }, 0)

  const items = itemsData ?? []

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-xl overflow-y-auto">
        <SheetHeader>
          <SheetTitle>New Purchase Order</SheetTitle>
          <SheetDescription>Create a purchase order for inventory restocking</SheetDescription>
        </SheetHeader>

        <Form {...form}>
          <form
            onSubmit={form.handleSubmit((v) => mutation.mutate(v))}
            className="mt-6 space-y-5"
          >
            {/* Header info */}
            <div className="grid grid-cols-2 gap-3">
              <FormField
                control={form.control}
                name="order_number"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Order Number</FormLabel>
                    <FormControl>
                      <Input {...field} value={field.value ?? ''} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="supplier_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Supplier</FormLabel>
                    <Select
                      value={field.value ?? 'none'}
                      onValueChange={(v) => field.onChange(v === 'none' ? null : v)}
                    >
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select supplier" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="none">No supplier</SelectItem>
                        {(suppliersData ?? []).map((s) => (
                          <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <FormField
                control={form.control}
                name="ordered_at"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Order Date</FormLabel>
                    <FormControl>
                      <Input type="date" {...field} value={field.value ?? ''} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="expected_delivery_at"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Expected Delivery</FormLabel>
                    <FormControl>
                      <Input type="date" {...field} value={field.value ?? ''} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Line items */}
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <p className="text-sm font-medium">Line Items</p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="h-7 text-xs"
                  onClick={() => append({ item_id: '', qty_ordered: 1, unit_cost_cents: 0, notes: null })}
                >
                  <Plus className="mr-1 h-3 w-3" />
                  Add Line
                </Button>
              </div>

              {form.formState.errors.lines?.root && (
                <p className="text-xs text-destructive">{form.formState.errors.lines.root.message}</p>
              )}

              <div className="space-y-2">
                {fields.map((field, index) => (
                  <div key={field.id} className="rounded-lg border border-border p-3 space-y-2">
                    <div className="flex items-start gap-2">
                      <FormField
                        control={form.control}
                        name={`lines.${index}.item_id`}
                        render={({ field: f }) => (
                          <FormItem className="flex-1">
                            <Select value={f.value} onValueChange={f.onChange}>
                              <FormControl>
                                <SelectTrigger className="h-8">
                                  <SelectValue placeholder="Select item" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {items.map((item) => (
                                  <SelectItem key={item.id} value={item.id}>
                                    {item.name}
                                    {item.sku ? ` (${item.sku})` : ''}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 shrink-0 text-muted-foreground hover:text-destructive"
                        onClick={() => remove(index)}
                        disabled={fields.length === 1}
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </Button>
                    </div>

                    <div className="grid grid-cols-2 gap-2">
                      <FormField
                        control={form.control}
                        name={`lines.${index}.qty_ordered`}
                        render={({ field: f }) => (
                          <FormItem>
                            <FormLabel className="text-xs">Quantity</FormLabel>
                            <FormControl>
                              <Input type="number" step="1" min="1" className="h-8" {...f} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control}
                        name={`lines.${index}.unit_cost_cents`}
                        render={({ field: f }) => (
                          <FormItem>
                            <FormLabel className="text-xs">Unit Cost ($)</FormLabel>
                            <FormControl>
                              <Input
                                type="number"
                                step="0.01"
                                min="0"
                                className="h-8"
                                placeholder="0.00"
                                value={f.value / 100}
                                onChange={(e) =>
                                  f.onChange(Math.round(parseFloat(e.target.value || '0') * 100))
                                }
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>

                    <div className="flex items-center justify-between">
                      <FormField
                        control={form.control}
                        name={`lines.${index}.notes`}
                        render={({ field: f }) => (
                          <FormItem className="flex-1">
                            <FormControl>
                              <Input
                                placeholder="Line notes (optional)"
                                className="h-7 text-xs"
                                {...f}
                                value={f.value ?? ''}
                              />
                            </FormControl>
                          </FormItem>
                        )}
                      />
                      <span className="text-xs text-muted-foreground ml-2 shrink-0">
                        {formatCurrency(
                          (Number(form.watch(`lines.${index}.qty_ordered`)) || 0) *
                            (Number(form.watch(`lines.${index}.unit_cost_cents`)) || 0)
                        )}
                      </span>
                    </div>
                  </div>
                ))}
              </div>

              <div className="flex justify-end">
                <p className="text-sm font-medium">
                  Total: <span className="tabular-nums">{formatCurrency(orderTotal)}</span>
                </p>
              </div>
            </div>

            <FormField
              control={form.control}
              name="notes"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Notes</FormLabel>
                  <FormControl>
                    <Textarea
                      rows={2}
                      placeholder="Internal notes about this order..."
                      {...field}
                      value={field.value ?? ''}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="flex gap-2 pt-2">
              <Button
                type="button"
                variant="outline"
                className="flex-1"
                onClick={() => onOpenChange(false)}
              >
                Cancel
              </Button>
              <Button type="submit" className="flex-1" disabled={mutation.isPending}>
                {mutation.isPending ? 'Creating...' : 'Create Order'}
              </Button>
            </div>
          </form>
        </Form>
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Skeleton } from '@/components/ui/skeleton'
import { PurchaseOrderForm } from '@/components/inventory/PurchaseOrderForm'
import { PurchaseOrderDetail } from '@/components/inventory/PurchaseOrderDetail'
import { queryKeys } from '@/lib/query-keys'
import { formatCurrency, formatDate } from '@/lib/utils'
import { Plus, ShoppingCart } from 'lucide-react'
import type { PurchaseOrder, Supplier } from '@/lib/supabase/types'

type POWithRelations = PurchaseOrder & {
  suppliers: Pick<Supplier, 'id' | 'name'> | null
  line_count?: number
}

const STATUS_CONFIG = {
  draft: { label: 'Draft', classes: 'bg-[oklch(55%_0.02_264/0.15)] text-[oklch(45%_0.02_264)]' },
  ordered: { label: 'Ordered', classes: 'bg-[oklch(60%_0.2_200/0.15)] text-[oklch(50%_0.2_200)]' },
  partial: { label: 'Partial', classes: 'bg-[oklch(70%_0.16_72/0.15)] text-[oklch(60%_0.16_72)]' },
  received: { label: 'Received', classes: 'bg-[oklch(58%_0.18_145/0.15)] text-[oklch(48%_0.18_145)]' },
  cancelled: { label: 'Cancelled', classes: 'bg-[oklch(59%_0.22_27/0.15)] text-[oklch(59%_0.22_27)]' },
} as const

export function PurchaseOrdersTable() {
  const queryClient = useQueryClient()
  const [statusFilter, setStatusFilter] = useState('all')
  const [formOpen, setFormOpen] = useState(false)
  const [selectedId, setSelectedId] = useState<string | null>(null)

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.purchaseOrders({ status: statusFilter }),
    queryFn: async () => {
      const params = new URLSearchParams()
      if (statusFilter !== 'all') params.set('status', statusFilter)
      const res = await fetch(`/api/inventory/purchase-orders?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch purchase orders')
      const json = await res.json() as { data: POWithRelations[] }
      return json.data
    },
  })

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full" />
        ))}
      </div>
    )
  }

  const orders = data ?? []

  return (
    <>
      <div className="flex items-center gap-2 justify-between">
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="h-8 w-36">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Orders</SelectItem>
            <SelectItem value="draft">Draft</SelectItem>
            <SelectItem value="ordered">Ordered</SelectItem>
            <SelectItem value="partial">Partial</SelectItem>
            <SelectItem value="received">Received</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
        <Button size="sm" onClick={() => setFormOpen(true)}>
          <Plus className="mr-1.5 h-4 w-4" />
          New Order
        </Button>
      </div>

      {orders.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-3">
          <div className="rounded-xl bg-muted/50 p-4">
            <ShoppingCart className="h-8 w-8 text-muted-foreground/50" />
          </div>
          <div className="text-center space-y-1">
            <p className="text-sm font-medium">No purchase orders</p>
            <p className="text-xs text-muted-foreground">
              {statusFilter !== 'all'
                ? `No orders with status "${STATUS_CONFIG[statusFilter as keyof typeof STATUS_CONFIG]?.label}"`
                : 'Create your first purchase order to track restocking'}
            </p>
          </div>
          {statusFilter === 'all' && (
            <Button size="sm" variant="outline" onClick={() => setFormOpen(true)}>
              <Plus className="mr-1.5 h-4 w-4" />
              New Order
            </Button>
          )}
        </div>
      ) : (
        <div className="rounded-lg border border-border overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/30 hover:bg-muted/30">
                <TableHead className="text-xs">Order #</TableHead>
                <TableHead className="text-xs">Supplier</TableHead>
                <TableHead className="text-xs">Status</TableHead>
                <TableHead className="text-xs">Ordered</TableHead>
                <TableHead className="text-xs">Expected</TableHead>
                <TableHead className="text-xs text-right">Total</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {orders.map((po) => {
                const statusCfg = STATUS_CONFIG[po.status]
                return (
                  <TableRow
                    key={po.id}
                    className="cursor-pointer hover:bg-muted/20"
                    onClick={() => setSelectedId(po.id)}
                  >
                    <TableCell>
                      <span className="text-sm font-medium font-mono">{po.order_number}</span>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm text-muted-foreground">
                        {po.suppliers?.name ?? '—'}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span
                        className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium ${statusCfg.classes}`}
                      >
                        {statusCfg.label}
                      </span>
                    </TableCell>
                    <TableCell className="text-xs text-muted-foreground">
                      {po.ordered_at ? formatDate(po.ordered_at) : '—'}
                    </TableCell>
                    <TableCell className="text-xs text-muted-foreground">
                      {po.expected_delivery_at ? formatDate(po.expected_delivery_at) : '—'}
                    </TableCell>
                    <TableCell className="text-right text-sm tabular-nums">
                      {formatCurrency(po.total_cents)}
                    </TableCell>
                  </TableRow>
                )
              })}
            </TableBody>
          </Table>
        </div>
      )}

      <PurchaseOrderForm
        open={formOpen}
        onOpenChange={setFormOpen}
        onSuccess={() => {
          void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrders() })
        }}
      />

      {selectedId && (
        <PurchaseOrderDetail
          id={selectedId}
          open={true}
          onOpenChange={(open) => { if (!open) setSelectedId(null) }}
          onSuccess={() => {
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrders() })
          }}
        />
      )}
    </>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { ReceiveOrderForm } from '@/components/inventory/ReceiveOrderForm'
import { queryKeys } from '@/lib/query-keys'
import { formatCurrency, formatDate } from '@/lib/utils'
import { toast } from 'sonner'
import { PackageCheck } from 'lucide-react'
import type { PurchaseOrder, PurchaseOrderLine, InventoryItem, Supplier } from '@/lib/supabase/types'

type PODetail = PurchaseOrder & {
  suppliers: Pick<Supplier, 'id' | 'name' | 'email' | 'phone'> | null
  purchase_order_lines: (PurchaseOrderLine & {
    inventory_items: Pick<InventoryItem, 'id' | 'name' | 'unit'> | null
  })[]
}

const STATUS_CONFIG = {
  draft: { label: 'Draft', classes: 'bg-[oklch(55%_0.02_264/0.15)] text-[oklch(45%_0.02_264)]' },
  ordered: { label: 'Ordered', classes: 'bg-[oklch(60%_0.2_200/0.15)] text-[oklch(50%_0.2_200)]' },
  partial: { label: 'Partial', classes: 'bg-[oklch(70%_0.16_72/0.15)] text-[oklch(60%_0.16_72)]' },
  received: { label: 'Received', classes: 'bg-[oklch(58%_0.18_145/0.15)] text-[oklch(48%_0.18_145)]' },
  cancelled: { label: 'Cancelled', classes: 'bg-[oklch(59%_0.22_27/0.15)] text-[oklch(59%_0.22_27)]' },
} as const

interface PurchaseOrderDetailProps {
  id: string
  open: boolean
  onOpenChange: (open: boolean) => void
  onSuccess?: () => void
}

export function PurchaseOrderDetail({ id, open, onOpenChange, onSuccess }: PurchaseOrderDetailProps) {
  const queryClient = useQueryClient()
  const [receiveOpen, setReceiveOpen] = useState(false)

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.purchaseOrder(id),
    queryFn: async () => {
      const res = await fetch(`/api/inventory/purchase-orders/${id}`)
      if (!res.ok) throw new Error('Failed to fetch purchase order')
      const json = await res.json() as { data: PODetail }
      return json.data
    },
    enabled: open,
  })

  const cancelMutation = useMutation({
    mutationFn: async () => {
      const res = await fetch(`/api/inventory/purchase-orders/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'cancelled' }),
      })
      if (!res.ok) throw new Error('Failed to cancel order')
    },
    onSuccess: () => {
      toast.success('Order cancelled')
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrder(id) })
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrders() })
      onSuccess?.()
    },
    onError: () => toast.error('Failed to cancel order'),
  })

  if (isLoading || !data) {
    return (
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent className="w-full sm:max-w-xl overflow-y-auto">
          <SheetHeader>
            <Skeleton className="h-6 w-48" />
            <Skeleton className="h-4 w-32" />
          </SheetHeader>
          <div className="mt-6 space-y-3">
            {Array.from({ length: 5 }).map((_, i) => (
              <Skeleton key={i} className="h-10 w-full" />
            ))}
          </div>
        </SheetContent>
      </Sheet>
    )
  }

  const po = data
  const statusCfg = STATUS_CONFIG[po.status]
  const canReceive = po.status === 'ordered' || po.status === 'partial'
  const canCancel = po.status === 'draft' || po.status === 'ordered'

  return (
    <>
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent className="w-full sm:max-w-xl overflow-y-auto">
          <SheetHeader>
            <div className="flex items-start justify-between gap-2">
              <div>
                <SheetTitle className="font-mono">{po.order_number}</SheetTitle>
                <SheetDescription className="mt-1">
                  {po.suppliers?.name ?? 'No supplier'}
                  {po.ordered_at && ` · Ordered ${formatDate(po.ordered_at)}`}
                </SheetDescription>
              </div>
              <span
                className={`inline-flex items-center rounded-full px-2.5 py-1 text-xs font-medium ${statusCfg.classes}`}
              >
                {statusCfg.label}
              </span>
            </div>
          </SheetHeader>

          <div className="mt-6 space-y-5">
            {/* Meta */}
            <div className="grid grid-cols-2 gap-x-4 gap-y-2 text-sm">
              {po.expected_delivery_at && (
                <>
                  <span className="text-muted-foreground">Expected delivery</span>
                  <span>{formatDate(po.expected_delivery_at)}</span>
                </>
              )}
              {po.received_at && (
                <>
                  <span className="text-muted-foreground">Received</span>
                  <span>{formatDate(po.received_at)}</span>
                </>
              )}
              {po.suppliers?.email && (
                <>
                  <span className="text-muted-foreground">Supplier email</span>
                  <a href={`mailto:${po.suppliers.email}`} className="text-primary hover:underline truncate">
                    {po.suppliers.email}
                  </a>
                </>
              )}
            </div>

            {po.notes && (
              <div className="rounded-md bg-muted/40 px-3 py-2 text-sm text-muted-foreground">
                {po.notes}
              </div>
            )}

            {/* Line items */}
            <div>
              <p className="text-sm font-medium mb-2">Line Items</p>
              <div className="rounded-lg border border-border overflow-hidden">
                <Table>
                  <TableHeader>
                    <TableRow className="bg-muted/30 hover:bg-muted/30">
                      <TableHead className="text-xs">Item</TableHead>
                      <TableHead className="text-xs text-right">Ordered</TableHead>
                      <TableHead className="text-xs text-right">Received</TableHead>
                      <TableHead className="text-xs text-right">Unit Cost</TableHead>
                      <TableHead className="text-xs text-right">Total</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {po.purchase_order_lines.map((line) => (
                      <TableRow key={line.id}>
                        <TableCell className="text-sm">
                          {line.inventory_items?.name ?? '—'}
                        </TableCell>
                        <TableCell className="text-right text-sm tabular-nums">
                          {line.qty_ordered} {line.inventory_items?.unit ?? ''}
                        </TableCell>
                        <TableCell className="text-right text-sm tabular-nums">
                          <span
                            className={
                              line.qty_received >= line.qty_ordered
                                ? 'text-[oklch(48%_0.18_145)]'
                                : line.qty_received > 0
                                ? 'text-[oklch(60%_0.16_72)]'
                                : 'text-muted-foreground'
                            }
                          >
                            {line.qty_received} {line.inventory_items?.unit ?? ''}
                          </span>
                        </TableCell>
                        <TableCell className="text-right text-sm tabular-nums">
                          {formatCurrency(line.unit_cost_cents)}
                        </TableCell>
                        <TableCell className="text-right text-sm tabular-nums font-medium">
                          {formatCurrency(line.total_cents)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
              <div className="flex justify-end mt-2">
                <p className="text-sm font-semibold">
                  Total: <span className="tabular-nums">{formatCurrency(po.total_cents)}</span>
                </p>
              </div>
            </div>

            {/* Actions */}
            <div className="flex gap-2 pt-2 border-t border-border">
              {canReceive && (
                <Button
                  className="flex-1"
                  onClick={() => setReceiveOpen(true)}
                >
                  <PackageCheck className="mr-1.5 h-4 w-4" />
                  Receive Items
                </Button>
              )}
              {canCancel && (
                <Button
                  variant="outline"
                  className="text-destructive hover:text-destructive"
                  disabled={cancelMutation.isPending}
                  onClick={() => cancelMutation.mutate()}
                >
                  {cancelMutation.isPending ? 'Cancelling...' : 'Cancel Order'}
                </Button>
              )}
            </div>
          </div>
        </SheetContent>
      </Sheet>

      {canReceive && (
        <ReceiveOrderForm
          open={receiveOpen}
          onOpenChange={setReceiveOpen}
          po={po}
          onSuccess={() => {
            setReceiveOpen(false)
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrder(id) })
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrders() })
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
            void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.movements() })
            onSuccess?.()
          }}
        />
      )}
    </>
  )
}

'use client'

import { useState } from 'react'
import { useMutation } from '@tanstack/react-query'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'
import { formatCurrency } from '@/lib/utils'
import type { PurchaseOrder, PurchaseOrderLine, InventoryItem } from '@/lib/supabase/types'

type LineWithItem = PurchaseOrderLine & {
  inventory_items: Pick<InventoryItem, 'id' | 'name' | 'unit'> | null
}

type POWithLines = PurchaseOrder & {
  purchase_order_lines: LineWithItem[]
}

interface ReceiveOrderFormProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  po: POWithLines
  onSuccess?: () => void
}

export function ReceiveOrderForm({ open, onOpenChange, po, onSuccess }: ReceiveOrderFormProps) {
  const [quantities, setQuantities] = useState<Record<string, string>>(() => {
    const init: Record<string, string> = {}
    po.purchase_order_lines.forEach((line) => {
      const remaining = line.qty_ordered - line.qty_received
      init[line.id] = remaining > 0 ? String(remaining) : '0'
    })
    return init
  })

  const mutation = useMutation({
    mutationFn: async () => {
      const lines = po.purchase_order_lines.map((line) => ({
        line_id: line.id,
        qty_received: parseFloat(quantities[line.id] ?? '0') || 0,
      }))

      const res = await fetch(`/api/inventory/purchase-orders/${po.id}/receive`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ lines }),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to receive items')
      }
      return res.json()
    },
    onSuccess: () => {
      toast.success('Items received and stock updated')
      onSuccess?.()
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to receive items')
    },
  })

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Receive Items</DialogTitle>
          <DialogDescription>
            Enter quantities received for order {po.order_number}. Stock will be updated automatically.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-1 -mx-2">
          {/* Header */}
          <div className="grid grid-cols-[1fr_80px_80px] gap-2 px-2 pb-1">
            <span className="text-xs font-medium text-muted-foreground">Item</span>
            <span className="text-xs font-medium text-muted-foreground text-right">Ordered</span>
            <span className="text-xs font-medium text-muted-foreground text-right">Received</span>
          </div>

          {po.purchase_order_lines.map((line) => {
            const remaining = line.qty_ordered - line.qty_received
            const unit = line.inventory_items?.unit ?? ''
            return (
              <div
                key={line.id}
                className="grid grid-cols-[1fr_80px_80px] gap-2 items-center rounded-md px-2 py-2 hover:bg-muted/30"
              >
                <div className="min-w-0">
                  <p className="text-sm font-medium truncate">
                    {line.inventory_items?.name ?? '—'}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {formatCurrency(line.unit_cost_cents)} / {unit}
                    {line.qty_received > 0 && ` · ${line.qty_received} already received`}
                  </p>
                </div>
                <div className="text-right text-sm tabular-nums text-muted-foreground">
                  {line.qty_ordered} {unit}
                </div>
                <div className="flex items-center gap-1">
                  <Input
                    type="number"
                    step="0.5"
                    min="0"
                    max={remaining}
                    value={quantities[line.id] ?? '0'}
                    onChange={(e) =>
                      setQuantities((prev) => ({ ...prev, [line.id]: e.target.value }))
                    }
                    className="h-7 w-full text-right text-sm"
                    disabled={remaining <= 0}
                  />
                </div>
              </div>
            )
          })}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={() => mutation.mutate()} disabled={mutation.isPending}>
            {mutation.isPending ? 'Receiving...' : 'Confirm Receipt'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

